package com.clock.wallpaper;
import android.app.*;import android.content.*;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;
public class PermissionActivity extends Activity { @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(32,32,32,32);TextView t=new TextView(this);t.setText("Разрешение заставки\n\nОткройте системные настройки и включите для Clock Wallpaper пункт «Показывать поверх других приложений». Этот экран запускается отдельно от основных настроек Clock.");t.setTextSize(18);box.addView(t);Button go=new Button(this);go.setText("Открыть системные настройки разрешений");go.setOnClickListener(v->{try{startActivity(new Intent(Settings.ACTION_MANAGE_APPLICATIONS_SETTINGS));}catch(Exception e){startActivity(new Intent(Settings.ACTION_SETTINGS));}});box.addView(go);setContentView(box);}}
